use moloch_live_runtime::graph_discovery::Rotation;
use baal_transport_service::Scope;
use std::collections::{BTreeMap,BTreeSet};
use serde_json::json;
fn scope()->Scope{Scope{tournament_id:"bda92870-621e-47b0-bc3c-3602c5c26f55".into(),tournament_slug:"cup".into(),exchanges:BTreeMap::from([("101".into(),"1".into()),("102".into(),"2".into()),("103".into(),"3".into()),("104".into(),"4".into()),("105".into(),"5".into()),("106".into(),"6".into()),("107".into(),"7".into()),("108".into(),"7".into())])}}
fn set(ids:&[&str])->BTreeSet<String>{ids.iter().map(|s|s.to_string()).collect()}
#[test]fn priorities_then_rotation_visit_entire_scope_even_with_three_managed_roots(){let s=scope();let mut r=Rotation::new(&s);let f=set(&["104","105","106"]);let o=set(&["102","103"]);assert_eq!(r.next(&s,&f,&o).unwrap(),vec!["4","5","6"]);assert_eq!(r.next(&s,&f,&o).unwrap(),vec!["2","3","1"]);assert_eq!(r.next(&s,&f,&o).unwrap(),vec!["7","4","5"]);}
#[test]fn persistent_roundtrip_does_not_restart_first_three_on_each_process(){let s=scope();let mut r=Rotation::new(&s);assert_eq!(r.next(&s,&set(&["104"]),&set(&["102"])).unwrap(),vec!["4","2","1"]);let mut restored=Rotation::restore(serde_json::to_value(r).unwrap(),&s).unwrap();assert_eq!(restored.next(&s,&set(&["104"]),&set(&["102"])).unwrap(),vec!["3","5","6"]);assert_eq!(restored.next(&s,&set(&["104"]),&set(&["102"])).unwrap()[0],"7");}
#[test]fn duplicate_market_exchanges_and_foreign_priorities_never_expand_scope(){let s=scope();let mut r=Rotation::new(&s);let mut seen=BTreeSet::new();for _ in 0..3{let roots=r.next(&s,&set(&["108","999"]),&set(&["888"])).unwrap();assert!(roots.len()<=3);assert_eq!(roots.iter().collect::<BTreeSet<_>>().len(),roots.len());for m in roots{assert!(s.exchanges.values().any(|v|v==&m));seen.insert(m);}}assert_eq!(seen.len(),7);}
#[test]fn changed_scope_removes_old_roots_and_fairly_admits_new_market(){let s=scope();let mut r=Rotation::new(&s);r.next(&s,&set(&[]),&set(&[])).unwrap();let mut changed=s.clone();changed.exchanges.remove("101");changed.exchanges.insert("109".into(),"8".into());let roots=r.next(&changed,&set(&[]),&set(&[])).unwrap();assert!(!roots.contains(&"1".into()));let body=serde_json::to_value(&r).unwrap();assert!(body["lastServed"].get("1").is_none());}
#[test]fn malformed_saved_state_and_wrong_tournament_do_not_become_discovery_evidence(){let s=scope();for v in [json!({}),json!({"version":1,"tournamentId":s.tournament_id,"round":1,"lastServed":{"../escape":1}}),json!({"version":1,"tournamentId":"wrong","round":1,"lastServed":{}}),json!({"version":1,"tournamentId":s.tournament_id,"round":1,"lastServed":{"1":2}})]{assert!(Rotation::restore(v,&s).is_err());}let mut bad=s;bad.exchanges.insert("1".into(),"../x".into());assert!(Rotation::new(&bad).next(&bad,&set(&[]),&set(&[])).is_err());}

#[test]fn actual_persisted_cursor_load_keeps_next_roots_and_rejects_torn_bytes(){let s=scope();let mut r=Rotation::new(&s);let first=r.next(&s,&set(&[]),&set(&[])).unwrap();let p=std::env::temp_dir().join(format!("graph-rotation-{}-{}.json",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::write(&p,serde_json::to_vec(&r).unwrap()).unwrap();let mut restored=Rotation::load(&p,&s).unwrap();let next=restored.next(&s,&set(&[]),&set(&[])).unwrap();assert!(next.iter().all(|m|!first.contains(m)));std::fs::write(&p,b"{\"version\":").unwrap();assert!(Rotation::load(&p,&s).is_err());std::fs::remove_file(&p).unwrap();}
#[test]fn optional_empty_scope_has_no_roots_and_round_overflow_is_not_wraparound(){let mut s=scope();s.exchanges.clear();assert!(Rotation::new(&s).next(&s,&set(&[]),&set(&[])).unwrap().is_empty());let s=scope();let mut r=Rotation::restore(json!({"version":1,"tournamentId":s.tournament_id,"round":u64::MAX,"lastServed":{}}),&s).unwrap();assert_eq!(r.next(&s,&set(&[]),&set(&[])).err(),Some("GRAPH_ROTATION_ROUND_OVERFLOW"));}
